package net.civeira.phylax.integrationtest.features.oauth.alt;

import java.util.Optional;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;

import io.quarkus.arc.profile.IfBuildProfile;
import jakarta.annotation.Priority;
import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.inject.Alternative;
import net.civeira.phylax.features.oauth.tokensecurity.domain.TokenIntrospectionResult;
import net.civeira.phylax.features.oauth.tokensecurity.domain.gateway.TokenLookupGateway;

/**
 * In-memory test alternative for {@link TokenLookupGateway}.
 *
 * Responsibilities: - Pre-register active token records by JTI for test scenarios. - Simulate
 * revoked tokens by simply not registering them.
 *
 * Design notes: - Use {@link #storeByJti} to register an active result before introspecting. -
 * Tokens not found in the map are treated as inactive (revoked or never issued). - Call
 * {@link #clear()} in {@code @BeforeEach} to reset state between tests.
 */
@IfBuildProfile("test")
@Alternative
@Priority(1)
@ApplicationScoped
public class FixedTokenLookupGateway implements TokenLookupGateway {

  private final ConcurrentMap<String, TokenIntrospectionResult> byJti = new ConcurrentHashMap<>();
  private final Set<String> revokedJtis = ConcurrentHashMap.newKeySet();

  /**
   * Registers an active introspection result indexed by its JTI.
   *
   * @param jti JWT ID
   * @param result active result to return on lookup
   */
  public void storeByJti(String jti, TokenIntrospectionResult result) {
    byJti.put(jti, result);
    revokedJtis.remove(jti);
  }

  /**
   * Marks a JTI as revoked so the lookup returns empty even if a result was registered.
   *
   * @param jti JWT ID to revoke
   */
  public void revoke(String jti) {
    revokedJtis.add(jti);
    byJti.remove(jti);
  }

  /**
   * Clears all registered results and revocations.
   */
  public void clear() {
    byJti.clear();
    revokedJtis.clear();
  }

  @Override
  public Optional<TokenIntrospectionResult> lookupByJti(String tenantSlug, String jti) {
    if (revokedJtis.contains(jti)) {
      return Optional.empty();
    }
    return Optional.ofNullable(byJti.get(jti));
  }

  @Override
  public Optional<TokenIntrospectionResult> lookupByRawToken(String tenantSlug, String rawToken) {
    return Optional.empty();
  }
}
